/**
 * PI-1P — initial knowledge base: high-value product archetypes, each reasoned as a packaging designer
 * would (what the product is, how it behaves, how it is used and bought, what the pack must do).
 *
 * Internal editorial rules (PI1_ARCHETYPE_SOURCE, confidence "medium"): tendencies, not facts about one
 * brand. Regulatory requirements (tamper evidence, child resistance) stay "unknown": no obligation is
 * invented. No engine structure id appears here; the packaging resolver maps families to structures.
 */
import { PI1_ARCHETYPE_SOURCE } from "./provenance";
import type { PackagingRequirements, ProductArchetype, ProductIntelligence } from "./types";
import { PACKAGING_REQUIREMENT_KEYS } from "./vocabulary";

type Req = Partial<Record<keyof PackagingRequirements, "required" | "preferred" | "notRelevant">>;
type Fields = Omit<ProductIntelligence, "confidence" | "origin" | "provenance" | "packagingRequirements">;

/** Every requirement not stated is "unknown" (never a silent default). */
const req = (r: Req): PackagingRequirements =>
  Object.fromEntries(PACKAGING_REQUIREMENT_KEYS.map((k) => [k, r[k] ?? "unknown"])) as PackagingRequirements;

const arch = (id: string, fr: string, en: string, terms: string[], rationale: string, r: Req, f: Fields, catalogueProducts?: string[]): ProductArchetype => ({
  id, label: { fr, en }, terms, rationale, ...(catalogueProducts ? { catalogueProducts } : {}),
  intelligence: { ...f, packagingRequirements: req(r), confidence: "medium", origin: "ruleBased", provenance: [PI1_ARCHETYPE_SOURCE] },
});

