/** Deep-freeze: the knowledge base is read-only data. */
function deepFreeze<T>(o: T): T {
  if (o && typeof o === "object" && !Object.isFrozen(o)) {
    Object.freeze(o);
    for (const v of Object.values(o as object)) deepFreeze(v);
  }
  return o;
}

export const PRODUCT_ARCHETYPES: readonly ProductArchetype[] = deepFreeze(RAW);

const BY_ID = new Map(PRODUCT_ARCHETYPES.map((a) => [a.id, a]));
export const archetypeById = (id: string): ProductArchetype | undefined => BY_ID.get(id);
